import CATALOGUE from '@/content/adhan/catalogue.generated.json';
import PERSONAL from '@/content/adhan/personal.generated.json';

import { personalAdhanEnabled } from './config';

/**
 * The adhan voice library: types, validation and pure selection logic.
 *
 * Voices are generated by scripts/adhan/build-library.mjs from recordings whose licence was verified
 * (CC0 / CC BY / CC BY-SA) and whose audio passed a quality gate. Nothing here performs I/O.
 */
export type Prayer = 'fajr' | 'dhuhr' | 'asr' | 'maghrib' | 'isha';
export const PRAYERS: readonly Prayer[] = ['fajr', 'dhuhr', 'asr', 'maghrib', 'isha'];

export type VoiceKind = 'adhan' | 'fajr';
/** bundled: ships in the app · download: fetched on demand · local: a file the user picked from their own device. */
export type Delivery = 'bundled' | 'download' | 'local';
/** licensed: rights verified · personal: rights NOT verified, personal use only · custom: the user's own file. */
export type VoiceTier = 'licensed' | 'personal' | 'custom';
type L3 = Readonly<Record<'ar' | 'en' | 'fr', string>>;

export interface DirectSource {
  readonly url: string;
  readonly format: 'mp3' | 'm4a';
  readonly bytes: number;
  readonly sha256: string;
  readonly durationSec: number;
  /** Playback-time attenuation (dB, ≤ 0) that levels this raw file to the library target. */
  readonly gainDb: number;
  readonly trim: { readonly startSec: number; readonly endSec: number };
}

export interface VoiceCredit {
  readonly recordist: string;
  readonly licence: string;
  readonly licenceUrl: string | null;
  readonly sourceTitle: string;
  readonly sourceUrl: string;
  readonly modified: string;
  readonly shareAlike: boolean;
  readonly commercialUse: boolean;
  readonly verifiedOn: string;
}

export interface AdhanVoice {
  readonly id: string;
  /** Defaults to `licensed`. */
  readonly tier?: VoiceTier;
  /** Custom voices only: where the user's file lives in app storage. */
  readonly localUri?: string;
  readonly kind: VoiceKind;
  readonly name: L3;
  readonly place: (L3 & { readonly country: string }) | null;
  readonly style: L3 | null;
  readonly delivery: Delivery;
  /** The muezzin, and the evidence for naming them. Never filled from guesses. */
  readonly performer?: { readonly name: string; readonly basis: string } | null;
  /** Duration of the mastered full recording. */
  readonly durationSec: number;
  /** Mastered file (bundled asset, or hosted on the optional mirror). */
  readonly bytes: number;
  readonly sha256: string;
  readonly format: 'm4a' | 'mp3';
  readonly file: string;
  readonly direct: DirectSource | null;
  /** `file` (hosted catalogues only) is the clip's path on the mirror, so a voice that is not bundled can still preview. */
  readonly clip: { readonly durationSec: number; readonly endsOnPhrase: boolean; readonly file?: string } | null;
  readonly audio: {
    readonly lufs: number;
    readonly truePeak: number;
    readonly lra: number;
    readonly noiseFloorDb?: number;
    readonly voiceToBackgroundDb?: number;
    readonly sampleRateHz: number;
    readonly channels: number;
    readonly bitrateKbps: number;
  };
  readonly credit: VoiceCredit;
}

export interface AdhanCatalogue {
  readonly schemaVersion: 2;
  readonly generatedAt: string;
  readonly voices: readonly AdhanVoice[];
}

// ─── Validation ────────────────────────────────────────────────────────────────

const SHA256 = /^[0-9a-f]{64}$/;
const ID = /^[a-z0-9][a-z0-9-]{1,48}$/;
/** Only licences that permit commercial use, redistribution and adaptation. */
export const ALLOWED_LICENCES = /^(CC0|CC BY(-SA)? [2-4]\.\d)$/;
/** Hosts the app may download audio from (the optional mirror is added by the caller). */
export const TRUSTED_AUDIO_HOSTS: readonly string[] = ['upload.wikimedia.org'];

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const str = (v: unknown): v is string => typeof v === 'string' && v.length > 0;
const num = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const l3 = (v: unknown): v is L3 => isObj(v) && str(v.ar) && str(v.en) && str(v.fr);

export class CatalogueError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CatalogueError';
  }
}

export interface ValidateOptions {
  /** Extra trusted download hosts (the configured mirror). */
  readonly extraHosts?: readonly string[];
  /** Remote catalogues may list voices that exist only on the mirror (no pinned Commons copy). */
  readonly allowMirrorOnly?: boolean;
}

export function validateVoice(raw: unknown, options: ValidateOptions | readonly string[] = {}): AdhanVoice {
  const opts: ValidateOptions = Array.isArray(options) ? { extraHosts: options as readonly string[] } : (options as ValidateOptions);
  const extraHosts = opts.extraHosts ?? [];
  if (!isObj(raw)) throw new CatalogueError('voice is not an object');
  const id = raw.id;
  if (!str(id) || !ID.test(id)) throw new CatalogueError(`invalid id: ${String(id)}`);
  const fail = (m: string): never => {
    throw new CatalogueError(`${id}: ${m}`);
  };
  if (raw.kind !== 'adhan' && raw.kind !== 'fajr') fail('kind');
  if (!l3(raw.name)) fail('name');
  if (raw.place !== null && !(l3(raw.place) && str((raw.place as Record<string, unknown>).country))) fail('place');
  if (raw.style !== null && !l3(raw.style)) fail('style');
  if (raw.delivery !== 'bundled' && raw.delivery !== 'download') fail('delivery');
  const perf = raw.performer;
  if (perf !== undefined && perf !== null && !(isObj(perf) && str(perf.name) && str(perf.basis))) fail('performer');
  if (!num(raw.durationSec) || raw.durationSec < 30 || raw.durationSec > 600) fail('durationSec');
  if (!num(raw.bytes) || raw.bytes < 10_000) fail('bytes');
  if (!str(raw.sha256) || !SHA256.test(raw.sha256)) fail('sha256');
  if (raw.format !== 'm4a' || !str(raw.file) || !/^[a-z0-9-]+\.m4a$/.test(raw.file)) fail('file');
  const clip = raw.clip;
  if (!isObj(clip) || !num(clip.durationSec) || clip.durationSec <= 5 || clip.durationSec >= 30) fail('clip must be 5–30 s (iOS limit)');
  if (isObj(clip) && clip.file !== undefined && !(typeof clip.file === 'string' && /^clips\/[a-z0-9-]+\.mp3$/.test(clip.file))) fail('clip file');
  const audio = raw.audio;
  if (!isObj(audio) || !num(audio.lufs) || !num(audio.truePeak) || audio.truePeak > -0.9) fail('audio metrics / true peak');
  const credit = raw.credit;
  if (!isObj(credit) || !str(credit.recordist) || !str(credit.licence) || !str(credit.sourceUrl) || !str(credit.sourceTitle) || !str(credit.modified))
    fail('credit');
  const c = credit as Record<string, unknown>;
  if (!ALLOWED_LICENCES.test(String(c.licence))) fail(`licence "${String(c.licence)}" does not allow commercial redistribution`);
  if (c.commercialUse !== true) fail('commercialUse');
  const direct = raw.direct;
  if (raw.delivery === 'bundled' && direct !== null) fail('bundled voice must not have a direct source');
  if (raw.delivery === 'download') {
    if (direct === null && opts.allowMirrorOnly) return raw as unknown as AdhanVoice;
    if (!isObj(direct)) return fail('download voice needs a direct source');
    const d = direct as Record<string, unknown>;
    const url = String(d.url ?? '');
    let host = '';
    try {
      const u = new URL(url);
      if (u.protocol !== 'https:') fail('direct url must be https');
      host = u.hostname;
    } catch {
      fail('direct url');
    }
    if (![...TRUSTED_AUDIO_HOSTS, ...extraHosts].includes(host)) fail(`untrusted host ${host}`);
    if (d.format !== 'mp3' && d.format !== 'm4a') fail('direct format (iOS cannot play Ogg)');
    if (!num(d.bytes) || d.bytes < 10_000 || d.bytes > 60_000_000) fail('direct bytes');
    if (!str(d.sha256) || !SHA256.test(d.sha256)) fail('direct sha256');
    if (!num(d.gainDb) || d.gainDb > 0 || d.gainDb < -30) fail('direct gain must be an attenuation');
    const trim = d.trim as Record<string, unknown> | undefined;
    if (!trim || !num(trim.startSec) || !num(trim.endSec) || trim.endSec <= trim.startSec) fail('direct trim');
  }
  return raw as unknown as AdhanVoice;
}

/** Validates a whole catalogue. Invalid voices are dropped (never crash on remote data); returns what was rejected. */
export function parseCatalogue(raw: unknown, options: ValidateOptions | readonly string[] = {}): { catalogue: AdhanCatalogue; rejected: string[] } {
  if (!isObj(raw) || raw.schemaVersion !== 2 || !Array.isArray(raw.voices)) throw new CatalogueError('unsupported catalogue');
  const voices: AdhanVoice[] = [];
  const rejected: string[] = [];
  const seen = new Set<string>();
  for (const v of raw.voices) {
    try {
      const ok = validateVoice(v, options);
      if (seen.has(ok.id)) throw new CatalogueError(`${ok.id}: duplicate`);
      seen.add(ok.id);
      voices.push(ok);
    } catch (e) {
      rejected.push(e instanceof Error ? e.message : 'invalid voice');
    }
  }
  return { catalogue: { schemaVersion: 2, generatedAt: String(raw.generatedAt ?? ''), voices }, rejected };
}

/** The catalogue that ships with the app (validated at module load; a broken build fails loudly in tests). */
export const BUNDLED_CATALOGUE: AdhanCatalogue = parseCatalogue(CATALOGUE).catalogue;

let voicesVersion = 0;
const voiceListeners = new Set<() => void>();

// ─── Personal-use catalogue ───────────────────────────────────────────────────

/** Hosts the personal catalogue may download from. Never used for the licensed library. */
export const TRUSTED_PERSONAL_HOSTS: readonly string[] = ['raw.githubusercontent.com'];

/**
 * Validates one voice of the personal-use catalogue. Deliberately separate from `validateVoice` (the licensed path stays
 * strict): the licence text must say plainly that the rights are not verified, there is no commercial claim, and the
 * download is pinned by size and SHA-256 on an allow-listed host.
 */
export function validatePersonalVoice(raw: unknown): AdhanVoice {
  if (!isObj(raw)) throw new CatalogueError('voice is not an object');
  const id = raw.id;
  if (!str(id) || !ID.test(id)) throw new CatalogueError(`invalid id: ${String(id)}`);
  const fail = (m: string): never => {
    throw new CatalogueError(`${id}: ${m}`);
  };
  if (raw.tier !== 'personal') fail('tier');
  if (raw.kind !== 'adhan' && raw.kind !== 'fajr') fail('kind');
  if (!l3(raw.name)) fail('name');
  if (raw.delivery !== 'download') fail('delivery');
  if (!num(raw.durationSec) || raw.durationSec < 15 || raw.durationSec > 600) fail('durationSec');
  const credit = raw.credit;
  if (!isObj(credit) || !str(credit.licence) || !/^Personal use only/.test(credit.licence) || credit.commercialUse !== false)
    fail('credit must say personal use only');
  const d = raw.direct;
  if (!isObj(d)) return fail('direct source');
  let host = '';
  try {
    const u = new URL(String(d.url));
    if (u.protocol !== 'https:') fail('https');
    host = u.hostname;
  } catch {
    fail('direct url');
  }
  if (!TRUSTED_PERSONAL_HOSTS.includes(host)) fail(`untrusted host ${host}`);
  if (d.format !== 'mp3' || !num(d.bytes) || d.bytes < 10_000 || d.bytes > 60_000_000 || !str(d.sha256) || !SHA256.test(d.sha256)) fail('direct pin');
  if (!num(d.gainDb) || d.gainDb > 0 || d.gainDb < -30) fail('gain must be an attenuation');
  const trim = d.trim as Record<string, unknown> | undefined;
  if (!trim || !num(trim.startSec) || !num(trim.endSec) || trim.endSec <= trim.startSec) fail('trim');
  return raw as unknown as AdhanVoice;
}

export function parsePersonalCatalogue(raw: unknown): { voices: AdhanVoice[]; rejected: string[] } {
  if (!isObj(raw) || raw.schemaVersion !== 2 || raw.tier !== 'personal' || !Array.isArray(raw.voices))
    throw new CatalogueError('unsupported personal catalogue');
  const voices: AdhanVoice[] = [];
  const rejected: string[] = [];
  const seen = new Set<string>();
  for (const v of raw.voices) {
    try {
      const ok = validatePersonalVoice(v);
      if (seen.has(ok.id)) throw new CatalogueError(`${ok.id}: duplicate`);
      seen.add(ok.id);
      voices.push(ok);
    } catch (e) {
      rejected.push(e instanceof Error ? e.message : 'invalid voice');
    }
  }
  return { voices, rejected };
}

let personalVoices: readonly AdhanVoice[] = personalAdhanEnabled() ? parsePersonalCatalogue(PERSONAL).voices : [];
/** Test seam (and the single switch used by the app when the personal catalogue is enabled). */
export function setPersonalVoices(voices: readonly AdhanVoice[]): void {
  personalVoices = voices;
  voicesVersion++;
  voiceListeners.forEach((l) => l());
}

/** Voices the user added from their own device. */
let customVoices: readonly AdhanVoice[] = [];
export function setCustomVoices(voices: readonly AdhanVoice[]): void {
  customVoices = voices;
  voicesVersion++;
  voiceListeners.forEach((l) => l());
}

export const tierOf = (v: AdhanVoice): VoiceTier => v.tier ?? 'licensed';
/** Playable without a download (ships in the app, or is the user's own file). */
export const isLocalVoice = (v: AdhanVoice): boolean => v.delivery !== 'download';

// ─── Lookup ──────────────────────────────────────────────────────────────────

/** Extra voices from a remote catalogue (cached); bundled voices always win on id clashes. */
let remoteExtras: readonly AdhanVoice[] = [];
export function setRemoteVoices(voices: readonly AdhanVoice[]): void {
  const bundled = new Set(BUNDLED_CATALOGUE.voices.map((v) => v.id));
  remoteExtras = voices.filter((v) => !bundled.has(v.id));
  voicesVersion++;
  voiceListeners.forEach((l) => l());
}

/** For `useSyncExternalStore`: re-render when the voice list changes. */
export const subscribeVoices = (listener: () => void): (() => void) => {
  voiceListeners.add(listener);
  return () => voiceListeners.delete(listener);
};
export const getVoicesVersion = (): number => voicesVersion;

export function allVoices(): readonly AdhanVoice[] {
  return [...BUNDLED_CATALOGUE.voices, ...remoteExtras, ...personalVoices, ...customVoices];
}

export function voiceById(id: string): AdhanVoice | null {
  return allVoices().find((v) => v.id === id) ?? null;
}

export const DEFAULT_VOICE_ID = 'aaqib-azeez';
export const DEFAULT_FAJR_VOICE_ID = 'malmo-fajr';

/** Package id used by the download manager for a voice. */
export const voicePackageId = (voiceId: string): string => `adhan.${voiceId}`;
export const voiceIdOfPackage = (packageId: string): string | null => (packageId.startsWith('adhan.') ? packageId.slice(6) : null);

export const isDownloadable = (v: AdhanVoice): boolean => v.delivery === 'download';

// ─── Selection ───────────────────────────────────────────────────────────────

export interface VoiceSettings {
  /** Used for every prayer without its own choice. */
  readonly defaultVoice: string;
  /** Per-prayer override; `null` = use the default (Fajr falls back to the Fajr default). */
  readonly byPrayer: Readonly<Record<Prayer, string | null>>;
}

/**
 * Which voice plays for a prayer. Order: the prayer's own choice → (Fajr only) the built-in Fajr adhan →
 * the default voice. A chosen voice that is not usable right now (deleted download) falls back to the next
 * candidate, and finally to a bundled voice, so the adhan is never silent because of a missing file.
 */
/**
 * A Fajr adhan contains an extra phrase («الصلاة خير من النوم»), so it may only sound at Fajr. Regular adhans may be
 * used at Fajr if the user insists, but never the other way round.
 */
export function voiceFitsPrayer(voice: AdhanVoice, prayer: Prayer): boolean {
  return voice.kind === 'adhan' || prayer === 'fajr';
}

export function resolveVoice(prayer: Prayer, settings: VoiceSettings, isAvailable: (voiceId: string) => boolean): AdhanVoice {
  const chain = [settings.byPrayer[prayer], prayer === 'fajr' ? DEFAULT_FAJR_VOICE_ID : null, settings.defaultVoice, DEFAULT_VOICE_ID];
  for (const id of chain) {
    if (!id) continue;
    const v = voiceById(id);
    if (v && voiceFitsPrayer(v, prayer) && isAvailable(v.id)) return v;
  }
  const bundled = BUNDLED_CATALOGUE.voices.find((v) => v.delivery === 'bundled' && voiceFitsPrayer(v, prayer));
  if (!bundled) throw new CatalogueError('catalogue has no bundled voice');
  return bundled;
}

/** Playback levelling for an installed file: mastered files need none, raw Commons files carry gain/trim. */
export function playbackProfile(voice: AdhanVoice, file: string): { gainDb: number; startSec: number; endSec: number | null; fadeOutSec: number } {
  if (file.endsWith('.m4a') || !voice.direct) return { gainDb: 0, startSec: 0, endSec: null, fadeOutSec: 0 };
  return { gainDb: voice.direct.gainDb, startSec: voice.direct.trim.startSec, endSec: voice.direct.trim.endSec, fadeOutSec: 1.4 };
}

export const dbToVolume = (db: number): number => Math.min(1, Math.max(0, 10 ** (db / 20)));

/** Total bytes the user would download for the not-yet-installed voices. */
export function downloadSize(voice: AdhanVoice): number {
  return voice.direct?.bytes ?? voice.bytes;
}

export function displayDuration(sec: number): string {
  const m = Math.floor(sec / 60);
  const s = Math.round(sec % 60);
  return `${m}:${String(s).padStart(2, '0')}`;
}
